import {BUILDING_GRID,buildingGridEnabled,buildingCellLabel} from './ea-building-grid.mjs?v=ea-160-courtyard-20261008-r11';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=v=>Array.isArray(v)?v:[];
const names={wood:'灵木',stone:'青石',herb:'灵草',food:'口粮',jade:'灵石',crystal:'灵晶',insight:'道韵',weapon:'兵器',armor:'衣甲',artifact:'法器',accessory:'饰物','pill:heal':'回春散','pill:qi':'聚气丹','pill:spirit':'灵息丹','pill:foundation':'筑基丹'};
const cost=v=>Object.entries(v||{}).filter(([,n])=>n).map(([k,n])=>`${names[k]||k} ${Math.ceil(n)}`).join(' · ')||'无额外材料';
const B=(label,command,args=[],reason='')=>`<button type="button" class="secondary" data-ui-action="${E(command)}" data-ui-args="${E(JSON.stringify(args))}"${reason?` disabled title="${E(reason)}"`:''}>${E(label)}</button>`;
const C=(title,body,key)=>`<article class="sr-card" data-key="${E(key||title)}"><h4>${E(title)}</h4>${body}</article>`;
const phases={moving:'实际行走',working:'正在劳动',paused:'条件未满足，保留进度',home:'已实际抵院',market:'坊市装运',channeling:'现场接引',descending:'实际跨界',present:'来客在场',aiding:'现场护界',stranded:'有限界门已关闭','to-anchor':'实际赶往接引台','to-client':'前往客商',repairing:'实际修箱','awaiting-payment':'等待客商实际送款','not-present':'尚未实际抵院',finished:'本约完成',settled:'已结清',unmet:'尚未接洽',geography:'查验地方旧约','transport-capability':'办理实际行旅契约',boarded:'已登乘',used:'已到达',waiting:'候班',reserved:'已预留',executing:'实际执行',blocked:'等待条件',completed:'已完成',cancelled:'已取消',available:'可商议',accepted:'已接下',declined:'已拒绝',delivered:'已交付',carrying:'携带途中','to-source':'前往取料',foundation:'打地基',structure:'立结构',finishing:'收尾',windup:'起手',execute:'执行',recovery:'收势',active:'已生效',unverified:'尚未核实',corroborated:'有事实互证',uncertain:'尚不确定',interrupted:'已中止',paid:'已兑付',corrected:'已纠正',retained:'保护留存',dissipated:'已消散',returning:'正在收回',returned:'已收回',destroyed:'已损毁',production:'生产',transport:'搬运',replenish:'恢复来源',trade:'交易',teach:'授业','pill-craft':'实际炼丹','soul-retain':'魂魄保护','avatar-form':'形成化身','lifespan-extend':'炼化延寿灵剂','high-chapter':'研取高阶续篇','high-material':'取得突破灵材','high-study':'共享续篇研习','high-material-gift':'实际交接灵材',overdue:'已逾期',fulfilled:'已履行',released:'已协商解除',breached:'违约后果持续',proposed:'待签成',unasked:'尚未商议',cooperating:'共同合作',rest:'休息',study:'研习',retrain:'转修',breakthrough:'突破','foundation-source':'准备筑基',sign:'签署',deliver:'交付',release:'解除',outbound:'实际赶路',walking:'现场行走',observing:'现场查验',recalled:'已收束观察','counter-divination':'现场消解息纹',content:'现场文书与交付',divine:'有锚卜算',investigate:'现场查证',walk:'实际行走',interact:'现场交互',guard:'护卫',focus:'协同压制',rally:'集结',retreat:'撤离'};const phase=v=>phases[v]||String(v??'等待');
