const S=t=>`<p class="sr-state" role="status">${E(t)}</p>`;
const options=(values,selected)=>values.map(v=>typeof v==='string'?{id:v,name:v}:v).map(v=>`<option value="${E(v.id)}"${v.id===selected?' selected':''}>${E(v.name||v.label||v.id)}</option>`).join('');
const F=(command,fields,extra='',button='确认')=>`<form class="sr-form" data-ui-form="sr" data-command="${E(command)}">${fields}${extra}<button type="submit" class="primary">${E(button)}</button></form>`;
const input=(name,label,{value='',type='text',min,max,step}={})=>`<label>${E(label)}<input data-ui-draft name="${E(name)}" type="${type}" value="${E(value)}"${min!==undefined?` min="${min}"`:''}${max!==undefined?` max="${max}"`:''}${step!==undefined?` step="${step}"`:''}${name==='key'?'':' required'}></label>`;
